#!/usr/bin/env python3
# AI: below section was generated by an AI
"""
Write guard (办公模式门禁) for the WLED light-recipe skill.

Why this exists
---------------
The product policy is: writes to the LAN WLED must only ever happen while the
operator is working inside Doubao's "办公任务 / 办公模式" (office task mode).
A skill cannot read Doubao's UI mode, so this guard converts that policy into an
explicit, auditable switch stored in config.json:

    "safety": { "allow_write": false }      # default = LOCKED

Required flow (what the skill must do):
    1. Ask the user to confirm they are in 办公模式 (office task mode).
    2. python3 scripts/guard.py --enable --confirm-office-mode
    3. ... create / apply / save recipes ...
    4. python3 scripts/guard.py --disable        # lock again when finished

Every script that writes to the device (apply_recipe / apply_dynamic_recipe /
apply_video_recipe / import_recipe / save_preset / upload_palette / sync_devices)
calls require_write() first and refuses to touch the device while locked.

Usage:
    python3 scripts/guard.py --status
    python3 scripts/guard.py --enable --confirm-office-mode
    python3 scripts/guard.py --disable

Output: JSON with {allowed, message, ...}
"""
import json
import os
import sys

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
SKILL_DIR = os.path.dirname(SCRIPT_DIR)
CONFIG_PATH = os.path.join(SKILL_DIR, "config.json")

DEFAULT_ALLOW = False  # locked by default — must be explicitly enabled

LOCKED_MESSAGE = (
    "写入已锁定：需在豆包「办公模式（办公任务）」下操作。"
    "请先让用户确认已处于办公模式，然后执行："
    "python3 scripts/guard.py --enable --confirm-office-mode"
)


def load_config():
    with open(CONFIG_PATH, "r", encoding="utf-8") as f:
        return json.load(f)


def save_config(config):
    with open(CONFIG_PATH, "w", encoding="utf-8") as f:
        json.dump(config, f, indent=2, ensure_ascii=False)
        f.write("\n")


def is_write_allowed(config=None):
    """Return True only when config.safety.allow_write is explicitly true."""
    if config is None:
        try:
            config = load_config()
        except Exception:
            return DEFAULT_ALLOW
    safety = config.get("safety", {}) or {}
    value = safety.get("allow_write", DEFAULT_ALLOW)
    return bool(value)


def check_write(config=None):
    """Return (allowed: bool, message: str)."""
    allowed = is_write_allowed(config)
    if allowed:
        return True, "写入已解锁（办公模式）"
    return False, LOCKED_MESSAGE


def blocked_result(action="write"):
    """Standard JSON payload for a blocked write attempt."""
    return {
        "success": False,
        "blocked": True,
        "reason": "write_locked",
        "action": action,
        "message": LOCKED_MESSAGE,
    }


def require_write(config=None, action="write"):
    """Return None when the write is allowed, otherwise a blocked_result dict."""
    allowed, _ = check_write(config)
    if allowed:
        return None
    return blocked_result(action)


def set_write_allowed(enabled):
    config = load_config()
    safety = config.get("safety")
    if not isinstance(safety, dict):
        safety = {}
        config["safety"] = safety
    safety["allow_write"] = bool(enabled)
    save_config(config)
    return is_write_allowed(config)


def main():
    if "--help" in sys.argv or "-h" in sys.argv:
        print(__doc__)
        sys.exit(0)

    if "--enable" in sys.argv:
        if "--confirm-office-mode" not in sys.argv:
            print(json.dumps({
                "success": False,
                "allowed": is_write_allowed(),
                "message": ("拒绝解锁：必须显式确认已处于豆包办公模式。"
                            "请先与用户确认，再加 --confirm-office-mode 重新执行。"),
            }, indent=2, ensure_ascii=False))
            sys.exit(1)
        allowed = set_write_allowed(True)
        print(json.dumps({
            "success": True,
            "allowed": allowed,
            "message": "写入已解锁（办公模式）。完成操作后请执行 --disable 重新锁定。",
        }, indent=2, ensure_ascii=False))
        sys.exit(0)

    if "--disable" in sys.argv:
        allowed = set_write_allowed(False)
        print(json.dumps({
            "success": True,
            "allowed": allowed,
            "message": "写入已锁定。",
        }, indent=2, ensure_ascii=False))
        sys.exit(0)

    # default / --status
    allowed, message = check_write()
    print(json.dumps({
        "success": True,
        "allowed": allowed,
        "config_path": CONFIG_PATH,
        "message": message,
    }, indent=2, ensure_ascii=False))
    sys.exit(0)


if __name__ == "__main__":
    main()
# AI: end
